"use client";

import { useEffect, useState, type FormEvent } from "react";
import { useRouter } from "next/navigation";
import { ArrowRight, Landmark, ShieldCheck } from "lucide-react";
import { createClient } from "@supabase/supabase-js";
import { createSupabaseBrowserClient } from "@/lib/supabase/browser";
import { getRoleDashboardPath } from "@/lib/auth/roles";

export default function LoginPage() {
  const router = useRouter();
  const [email, setEmail] = useState("");
  const [password, setPassword] = useState("");
  const [error, setError] = useState("");
  const [busy, setBusy] = useState(false);
  const [checkingSession, setCheckingSession] = useState(true);

  useEffect(() => {
    let active = true;

    async function resumeLandingSession() {
      const supabase = createSupabaseBrowserClient();
      const { data: { session: cookieSession } } = await supabase.auth.getSession();
      let session = cookieSession;

      if (!session) {
        // The existing landing app uses supabase-js local storage. Import that
        // session into the SSR client so server route guards can read its cookies.
        const landingClient = createClient(
          process.env.NEXT_PUBLIC_SUPABASE_URL!,
          process.env.NEXT_PUBLIC_SUPABASE_ANON_KEY!,
        );
        const { data } = await landingClient.auth.getSession();
        session = data.session;

        if (session) {
          const { error: sessionError } = await supabase.auth.setSession({
            access_token: session.access_token,
            refresh_token: session.refresh_token,
          });
          if (sessionError) session = null;
        }
      }

      if (!session) {
        if (active) setCheckingSession(false);
        return;
      }

      const { data: profile, error: profileError } = await supabase
        .from("profiles")
        .select("role, is_active")
        .eq("id", session.user.id)
        .single();
      const destination = profileError || !profile?.is_active ? null : getRoleDashboardPath(profile.role);

      if (active && destination) {
        router.replace(destination);
        router.refresh();
        return;
      }

      if (active) {
        setError("This account doesn't have an active AlertBarangay role. Contact your administrator.");
        setCheckingSession(false);
      }
    }

    void resumeLandingSession().catch(() => {
      if (active) setCheckingSession(false);
    });

    return () => { active = false; };
  }, [router]);

  async function submit(event: FormEvent<HTMLFormElement>) {
    event.preventDefault(); setBusy(true); setError("");
    const supabase = createSupabaseBrowserClient();
    const { data, error: signInError } = await supabase.auth.signInWithPassword({ email, password });
    if (signInError) { setError("We couldn't sign you in. Check your email and password."); setBusy(false); return; }
    const { data: profile, error: profileError } = await supabase
      .from("profiles")
      .select("role, is_active")
      .eq("id", data.user.id)
      .single();
    const destination = profileError || !profile?.is_active ? null : getRoleDashboardPath(profile.role);
    if (!destination) {
      await supabase.auth.signOut();
      setError("This account doesn't have an active AlertBarangay role. Contact your administrator.");
      setBusy(false);
      return;
    }
    router.replace(destination); router.refresh();
  }

  if (checkingSession) return <main className="login-page" aria-label="Opening your dashboard">
    <section className="login-panel"><p className="muted">Opening your dashboard…</p></section>
  </main>;

  return <main className="login-page">
    <section className="login-panel">
      <div className="brand-badge login-badge"><Landmark size={23} /></div>
      <div className="eyebrow">ALERTBARANGAY</div>
      <h1>Welcome back</h1>
      <p className="muted">Sign in to continue to your barangay dashboard.</p>
      <form className="login-form" onSubmit={submit}>
        <label>Email address<input type="email" autoComplete="username" required value={email} onChange={(e) => setEmail(e.target.value)} placeholder="you@barangay.gov.ph" /></label>
        <label>Password<input type="password" autoComplete="current-password" required value={password} onChange={(e) => setPassword(e.target.value)} placeholder="Enter your password" /></label>
        {error && <div className="inline-error" role="alert">{error}</div>}
        <button className="button primary login-submit" disabled={busy}>{busy ? "Signing in…" : "Sign in"}<ArrowRight size={17} /></button>
      </form>
      <div className="login-footnote"><ShieldCheck size={16} /> Your account access is verified securely.</div>
    </section>
    <aside className="login-aside"><div className="aside-mark"><Landmark size={26} /></div><span>ALERTBARANGAY</span><h2>Better connected.<br />Safer together.</h2><p>Sign in to access your local community dashboard.</p><div className="aside-decoration" /></aside>
  </main>;
}
